<?php require __DIR__.'/app/bootstrap.php'; $pageTitle='Categories — NEXT TECH'; $cats=db()->query("SELECT c.*,COUNT(p.id) product_count FROM categories c LEFT JOIN products p ON p.category_id=c.id AND p.status='active' WHERE c.is_active=1 GROUP BY c.id ORDER BY c.sort_order,c.name")->fetchAll(); require __DIR__.'/includes/header.php'; ?><section class="page-intro"><span class="eyebrow">DISCOVER</span><h1>Categories</h1><p>Find the right technology for your setup.</p></section><div class="category-grid"><?php foreach($cats as $c): ?><a class="category-card" href="<?=e(url('category.php?slug='.rawurlencode($c['slug'])))?>"><span class="category-icon">◇</span><strong><?=e($c['name'])?></strong><small><?=(int)$c['product_count']?> products</small></a><?php endforeach; ?></div><?php require __DIR__.'/includes/footer.php'; ?>
